-- Idempotent fixed IDs. Public bank contains 60 Vietnamese sample questions.
-- Optional bundled illustrations; deterministic updates also upgrade an existing demo seed.
UPDATE QUIZZES SET cover_asset_id=CASE id WHEN 1 THEN 'quiz-cover-science' WHEN 2 THEN 'quiz-cover-history' ELSE 'quiz-cover-general' END WHERE id IN (1,2,3);
UPDATE QUESTIONS SET question_asset_id='question-sample', explanation_asset_id='question-sample' WHERE id IN (101,201,301);
UPDATE QUESTIONS SET content='Trong bài tập đọc hiểu dưới đây, hãy đọc kỹ yêu cầu trước khi chọn đáp án. Một nhóm học sinh có một bạn ban đầu, sau đó thêm một bạn tham gia vào nhóm để cùng chuẩn bị phần trình bày kiến thức khoa học. Hỏi hiện tại nhóm có tất cả bao nhiêu bạn? Chọn đúng một phương án trong các lựa chọn.' WHERE id=101;
